package constructors.class_problems;
public class BusRouteRankingEngine {static class BusRoute{String routeCode,routeName;int priority;BusRoute(String c,String n,int p){this.routeCode=c;routeName=n;priority=p;}BusRoute(String c,String n){this(c,n,3);}int compareTo(BusRoute o){int x=Integer.compare(o.priority,priority);if(x!=0)return x;x=routeCode.compareToIgnoreCase(o.routeCode);if(x!=0)return x;return Integer.compare(routeName.length(),o.routeName.length());}}static BusRoute[] rankRoutes(BusRoute[] r){BusRoute[] a=r.clone();for(int i=0;i<a.length-1;i++)for(int j=0;j<a.length-1-i;j++)if(a[j].compareTo(a[j+1])>0){BusRoute t=a[j];a[j]=a[j+1];a[j+1]=t;}return a;}public static void main(String[]a){BusRoute[] r=rankRoutes(new BusRoute[]{new BusRoute("RT205L","Airport Express",3),new BusRoute("rt201j","City Central",4),new BusRoute("RT299T","Night Service")});for(BusRoute x:r)System.out.println(x.routeCode);}}